```python
source = """< ( ( [ < > { [ { ( ) } ] < { < { } > [ ( < > ) ] } > } [ < > ] ] ) { { ( { ( ( [ ( [ ] ) ] < { } > ) ) { { ( [ [ ] ] ) } [ ( ) ] { { [ ] } } } } ) } ( { } ) }"""

submitted = """< ( ( [ < > { [ { ( ) } ] < { < { } > [ ( < > ) ] } > } [ < > ] ] ) { { ( { ( ( [ ( [ ] ) ] < { } > ) ) { { ( [ [ ] ] ) } [ ( ) ] { { [ ] } } } } ) } ( { } ) } } } >"""

pairs = {"(": ")", "[": "]", "{": "}", "<": ">"}
closers = set(pairs.values())


def scan(tokens):
    stack = []
    for position, token in enumerate(tokens, 1):
        if token in pairs:
            stack.append(token)
        elif token in closers:
            if not stack:
                return stack, f"Unexpected {token!r} at token {position}"
            expected = pairs[stack[-1]]
            if token != expected:
                return stack, (
                    f"At token {position}: expected {expected!r}, got {token!r}"
                )
            stack.pop()
        else:
            return stack, f"Invalid token {token!r} at token {position}"
    return stack, None


original_tokens = source.split()
answer_tokens = submitted.split()
stack, source_error = scan(original_tokens)

if source_error:
    print("Input error:", source_error)
    print("UNSUPPORTED: appending closers cannot repair this input.")
    print("CHECK UNKNOWN")
else:
    required = [pairs[opening] for opening in reversed(stack)]
    expected_tokens = original_tokens + required
    answer_stack, answer_error = scan(answer_tokens)

    print("Unclosed opening brackets:", " ".join(stack) or "(none)")
    print("Required appended brackets:", " ".join(required) or "(none)")
    print("Expected result:", " ".join(expected_tokens))
    print(
        "Original sequence preserved:",
        answer_tokens[:len(original_tokens)] == original_tokens,
    )
    if answer_error:
        print("Submitted answer error:", answer_error)
    elif answer_stack:
        print("Submitted answer leaves unclosed brackets:", " ".join(answer_stack))
    else:
        print("Submitted answer is balanced.")

    print("CHECK PASS" if answer_tokens == expected_tokens else "CHECK FAIL")
